from solution import make_palindrome, is_palindrome
import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference(s: str) -> str:
    """Obviously-correct brute force: first i where suffix is palindrome."""
    if s == s[::-1]:
        return s
    for i in range(len(s)):
        suffix = s[i:]
        if suffix == suffix[::-1]:
            return s + s[:i][::-1]
    # single char suffix is always a palindrome; unreachable for non-empty
    return s + s[:-1][::-1]


# ---- concrete examples from spec ----

def test_example_empty():
    assert make_palindrome('') == ''


def test_example_cat():
    assert make_palindrome('cat') == 'catac'


def test_example_cata():
    assert make_palindrome('cata') == 'catac'


# ---- properties ----

@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=12))
def test_result_begins_with_input(s):
    r = make_palindrome(s)
    assert isinstance(r, str)
    assert r.startswith(s)


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=12))
def test_result_is_palindrome(s):
    r = make_palindrome(s)
    assert is_palindrome(r)
    assert r == r[::-1]


@given(st.text(alphabet=st.sampled_from(["a", "b"]), min_size=0, max_size=10))
def test_equivalence_to_reference_model(s):
    assert make_palindrome(s) == reference(s)


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=10))
def test_shortest_no_shorter_palindrome_with_prefix(s):
    r = make_palindrome(s)
    # every strictly shorter string that still begins with s must not be a palindrome
    # any palindrome beginning with s of length L < len(r) would have to equal r[:L]
    # only if r[:L] starts with s, i.e. L >= len(s); check none of those prefixes is a palindrome
    for L in range(len(s), len(r)):
        prefix = r[:L]
        assert prefix != prefix[::-1], f"shorter palindrome prefix exists for {s!r}"


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=10))
def test_length_is_minimal_matches_reference_length(s):
    r = make_palindrome(s)
    assert len(r) == len(reference(s))


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=10))
def test_length_bounds(s):
    r = make_palindrome(s)
    if len(s) == 0:
        assert r == ''
    else:
        assert len(s) <= len(r) <= 2 * len(s) - 1
        if is_palindrome(s):
            assert r == s


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=0, max_size=10))
def test_idempotence(s):
    r = make_palindrome(s)
    assert make_palindrome(r) == r


@given(st.text(alphabet=st.sampled_from(["a", "b", "c"]), min_size=1, max_size=10))
def test_uses_longest_palindromic_suffix(s):
    r = make_palindrome(s)
    # appended part must be reverse of prefix before the palindromic suffix
    k = len(r) - len(s)  # number of appended chars
    i = len(s) - k
    assert 0 <= i <= len(s)
    assert r == s + s[:i][::-1]
    assert is_palindrome(s[i:])
    # longest: no smaller i gives palindromic suffix
    for j in range(0, i):
        assert not is_palindrome(s[j:])


def test_explicit_palindromes_unchanged():
    for s in ["", "a", "aa", "aba", "abba", "abacaba", "racecar", "aaaa"]:
        assert make_palindrome(s) == s


def test_explicit_shortest_cases():
    cases = {
        "ab": "aba",
        "aaab": "aaabaaa",
        "cata": "catac",
        "cat": "catac",
        "race": "racecar",
        "abcd": "abcdcba",
        "aab": "aabaa",
        "abb": "abba",
    }
    for s, expected in cases.items():
        assert make_palindrome(s) == expected
        assert make_palindrome(s) == reference(s)
